   const auto payload=QString::fromUtf8(read(stk));bool inData=false;QJsonArray rows;for(auto line:payload.split('\n')){line=line.trimmed();if(line=="EphemerisTimePosVel"){inData=true;continue;}if(line=="END Ephemeris"){inData=false;continue;}if(!inData||line.isEmpty())continue;const auto cols=line.split(QRegularExpression("\\s+"),Qt::SkipEmptyParts);require(cols.size()==7,"STK row width differs");QJsonArray row;for(auto c:cols){bool ok=false;double value=c.toDouble(&ok);require(ok&&std::isfinite(value),"STK numeric field invalid");row.append(value);}rows.append(row);}rig.save(prefix+"rows.json",QJsonDocument(rows).toJson());require(rows.size()==22&&payload.contains("CoordinateSystem        J2000")&&payload.contains("DistanceUnit            Kilometers"),"STK complete trajectory/frame metadata absent");QJsonArray eligible;for(auto v:raw){auto r=v.toObject();if(r["phase"]==selected&&r["run_state"].toInt()==int(Gmat::SOLVEDPASS))eligible.append(r);}require(eligible.size()==(family=="Filter"?23:24),"Selected native estimator publication stream missing");for(int i=0;i<rows.size();++i)require(std::abs(rows[i].toArray()[0].toDouble()-60*(i/2))<1e-4,"STK measurement epoch/posterior census differs");const double epoch0=spec["a1_epoch"].toDouble(),radius=7000,rate=std::sqrt(mu/(radius*radius*radius)),speed=std::sqrt(mu/radius);auto verify=[&](double t,const QJsonArray&state){require(t>=-1e-4&&t<=600+1e-4,"STK state outside measurement span");const double a=rate*t,want[]={radius*std::cos(a),radius*std::sin(a),0.,-speed*std::sin(a),speed*std::cos(a),0.};for(int i=0;i<6;++i)require(std::abs(state[i].toDouble()-want[i])<(i<3?2e-5:2e-8),"STK state differs from independent noiseless circle");};for(auto v:eligible){auto r=v.toObject();verify((r["epoch"].toDouble()-epoch0)*86400,r["state"].toArray());}
